integer n, i, c, p, b, done, marg, xi, yi
integer ord(5), fbin(5), nbin(5)
double precision v(5), lo(5), hi(5)

read(5,*) n

# priority order -> column index (1 RDS, 2 VDD, 3 FMAX, 4 ILEAK, 5 VTH)
ord(1) = 3; ord(2) = 2; ord(3) = 1; ord(4) = 4; ord(5) = 5

# limits (1d30 means no limit)
lo(1) = 144.783d0; hi(1) = 1d30
lo(2) = 44.244d0;  hi(2) = 57.356d0
lo(3) = 211.279d0; hi(3) = 266.253d0
lo(4) = 312.485d0; hi(4) = 527.767d0
lo(5) = 368.162d0; hi(5) = 1d30

# fail bins per column
fbin(1) = 27; fbin(2) = 21; fbin(3) = 32; fbin(4) = 24; fbin(5) = 15

# bin if not measured (0 means skip)
nbin(1) = 34; nbin(2) = 34; nbin(3) = 0; nbin(4) = 34; nbin(5) = 34

for (i = 1; i <= n; i = i + 1) {
  read(5,*) xi, yi, (v(c), c = 1, 5)
  b = 0
  done = 0
  for (p = 1; p <= 5 & done == 0; p = p + 1) {
    c = ord(p)
    if (v(c) == -9999d0) {
      if (nbin(c) != 0) {
        b = nbin(c)
        done = 1
      }
    } else if (v(c) < lo(c) | v(c) > hi(c)) {
      b = fbin(c)
      done = 1
    }
  }
  if (done == 0) {
    marg = 0
    for (c = 1; c <= 5; c = c + 1) {
      if (v(c) != -9999d0) {
        if (10d0 * abs(v(c) - lo(c)) <= abs(lo(c))) marg = 1
        if (hi(c) < 1d29 & 10d0 * abs(v(c) - hi(c)) <= abs(hi(c))) marg = 1
      }
    }
    if (marg == 1) b = 10
    else b = 1
  }
  write(6,*) xi, yi, b
}
end

integer n, i, j, k, x, y, b, marg
integer v(5), lo(5), hi(5), fb(5), nm(5), ord(5), meas(5), hasl(5), hash(5)
double precision raw(5)

# table column j: 1=RDS 2=VDD 3=FMAX 4=ILEAK 5=VTH
# limits in thousandths (values have at most 3 decimals)
lo(1) = 144783; hasl(1) = 1; hash(1) = 0; hi(1) = 0; fb(1) = 27; nm(1) = 34
lo(2) = 44244;  hasl(2) = 1; hash(2) = 1; hi(2) = 57356; fb(2) = 21; nm(2) = 34
lo(3) = 211279; hasl(3) = 1; hash(3) = 1; hi(3) = 266253; fb(3) = 32; nm(3) = 0
lo(4) = 312485; hasl(4) = 1; hash(4) = 1; hi(4) = 527767; fb(4) = 24; nm(4) = 34
lo(5) = 368162; hasl(5) = 1; hash(5) = 0; hi(5) = 0; fb(5) = 15; nm(5) = 34

# priority order: FMAX, VDD, RDS, ILEAK, VTH
ord(1) = 3; ord(2) = 2; ord(3) = 1; ord(4) = 4; ord(5) = 5

read(5,*) n
for (i = 1; i <= n; i = i + 1) {
  read(5,*) x, y, (raw(j), j = 1, 5)
  for (j = 1; j <= 5; j = j + 1) {
    if (raw(j) == -9999d0) {
      meas(j) = 0
      v(j) = 0
    } else {
      meas(j) = 1
      v(j) = nint(raw(j) * 1000d0)
    }
  }

  b = 0
  k = 1
  while (k <= 5 & b == 0) {
    j = ord(k)
    if (meas(j) == 0) {
      if (nm(j) != 0) b = nm(j)
    } else {
      if (hasl(j) == 1 & v(j) < lo(j)) {
        b = fb(j)
      } else if (hash(j) == 1 & v(j) > hi(j)) {
        b = fb(j)
      }
    }
    k = k + 1
  }

  if (b == 0) {
    marg = 0
    for (j = 1; j <= 5; j = j + 1) {
      if (meas(j) == 1) {
        if (hasl(j) == 1) {
          if (10 * abs(v(j) - lo(j)) <= abs(lo(j))) marg = 1
        }
        if (hash(j) == 1) {
          if (10 * abs(v(j) - hi(j)) <= abs(hi(j))) marg = 1
        }
      }
    }
    if (marg == 1) {
      b = 10
    } else {
      b = 1
    }
  }

  write(6,*) x, y, b
}
end

integer n, i, j, c, k, x, y, b, done, marg
integer fb(5), nm(5), ord(5)
double precision v(5), lo(5), hi(5), t, lim

# limits, fail bins, not-measured bins (0 = skip), priority order
lo(1) = 144.783d0; hi(1) = 1d30;     fb(1) = 27; nm(1) = 34
lo(2) = 44.244d0;  hi(2) = 57.356d0; fb(2) = 21; nm(2) = 34
lo(3) = 211.279d0; hi(3) = 266.253d0; fb(3) = 32; nm(3) = 0
lo(4) = 312.485d0; hi(4) = 527.767d0; fb(4) = 24; nm(4) = 34
lo(5) = 368.162d0; hi(5) = 1d30;     fb(5) = 15; nm(5) = 34

ord(1) = 3
ord(2) = 2
ord(3) = 1
ord(4) = 4
ord(5) = 5

read(5,*) n
do i = 1, n {
  read(5,*) x, y, (v(j), j = 1, 5)
  b = 0
  done = 0
  k = 1
  while (done == 0 & k <= 5) {
    c = ord(k)
    t = v(c)
    if (t == -9999d0) {
      if (nm(c) != 0) {
        b = nm(c)
        done = 1
      }
    } else if (t < lo(c) | t > hi(c)) {
      b = fb(c)
      done = 1
    }
    k = k + 1
  }
  if (b == 0) {
    marg = 0
    do c = 1, 5 {
      if (v(c) != -9999d0) {
        lim = lo(c)
        if (abs(v(c) - lim) <= 0.1d0 * abs(lim)) marg = 1
        lim = hi(c)
        if (abs(v(c) - lim) <= 0.1d0 * abs(lim)) marg = 1
      }
    }
    if (marg == 1) b = 10
    else b = 1
  }
  write(6,*) x, y, b
}
end

integer n, i, j, k, x, y, bin, mg, dd, al
integer mv(5), lo(5), hi(5), fb(5), nb(5), hl(5), hh(5), ord(5)
double precision vals(5)

# columns 1..5 = RDS, VDD, FMAX, ILEAK, VTH; limits in milli-units
lo(1) = 144783; lo(2) = 44244; lo(3) = 211279; lo(4) = 312485; lo(5) = 368162
hi(1) = 0; hi(2) = 57356; hi(3) = 266253; hi(4) = 527767; hi(5) = 0
hl(1) = 1; hl(2) = 1; hl(3) = 1; hl(4) = 1; hl(5) = 1
hh(1) = 0; hh(2) = 1; hh(3) = 1; hh(4) = 1; hh(5) = 0
fb(1) = 27; fb(2) = 21; fb(3) = 32; fb(4) = 24; fb(5) = 15
nb(1) = 34; nb(2) = 34; nb(3) = 0; nb(4) = 34; nb(5) = 34
# priority order: FMAX, VDD, RDS, ILEAK, VTH
ord(1) = 3; ord(2) = 2; ord(3) = 1; ord(4) = 4; ord(5) = 5

read(5,*) n
do i = 1, n {
  read(5,*) x, y, (vals(j), j = 1, 5)
  for (j = 1; j <= 5; j = j + 1) {
    mv(j) = nint(vals(j) * 1000d0)
  }
  bin = 0
  for (k = 1; k <= 5; k = k + 1) {
    j = ord(k)
    if (mv(j) == -9999000) {
      if (nb(j) != 0) { bin = nb(j); break }
    } else if (hl(j) == 1 & mv(j) < lo(j)) {
      bin = fb(j); break
    } else if (hh(j) == 1 & mv(j) > hi(j)) {
      bin = fb(j); break
    }
  }
  if (bin == 0) {
    bin = 1
    mg = 0
    for (j = 1; j <= 5; j = j + 1) {
      if (mv(j) != -9999000) {
        if (hl(j) == 1) {
          dd = mv(j) - lo(j); if (dd < 0) dd = -dd
          al = lo(j); if (al < 0) al = -al
          if (10 * dd <= al) mg = 1
        }
        if (hh(j) == 1) {
          dd = mv(j) - hi(j); if (dd < 0) dd = -dd
          al = hi(j); if (al < 0) al = -al
          if (10 * dd <= al) mg = 1
        }
      }
    }
    if (mg == 1) bin = 10
  }
  write(6,*) x, y, bin
}
end

integer n, i, k, c, ix, iy, bin, done, mar
integer pr(5), lo(5), hi(5), fb(5), nb(5), haslo(5), hashi(5), nmf(5), m(5)
double precision v(5)

# Column order: 1 RDS, 2 VDD, 3 FMAX, 4 ILEAK, 5 VTH
# Limits are stored in milli-units (value * 1000) so comparisons are exact.
# nb(c) = 0 means "skip if not measured".
pr(1) = 3
pr(2) = 2
pr(3) = 1
pr(4) = 4
pr(5) = 5

lo(1) = 144783
haslo(1) = 1
hashi(1) = 0
fb(1) = 27
nb(1) = 34

lo(2) = 44244
haslo(2) = 1
hi(2) = 57356
hashi(2) = 1
fb(2) = 21
nb(2) = 34

lo(3) = 211279
haslo(3) = 1
hi(3) = 266253
hashi(3) = 1
fb(3) = 32
nb(3) = 0

lo(4) = 312485
haslo(4) = 1
hi(4) = 527767
hashi(4) = 1
fb(4) = 24
nb(4) = 34

lo(5) = 368162
haslo(5) = 1
hashi(5) = 0
fb(5) = 15
nb(5) = 34

read(5,*) n
do i = 1, n {
  read(5,*) ix, iy, (v(c), c = 1, 5)

  for (c = 1; c <= 5; c = c + 1) {
    if (v(c) == -9999d0) {
      nmf(c) = 1
      m(c) = 0
    }
    else {
      nmf(c) = 0
      m(c) = nint(v(c) * 1000d0)
    }
  }

  # Priority-ordered tests
  bin = 0
  done = 0
  for (k = 1; k <= 5; k = k + 1) {
    if (done == 0) {
      c = pr(k)
      if (nmf(c) == 1) {
        if (nb(c) != 0) {
          bin = nb(c)
          done = 1
        }
      }
      else {
        if (haslo(c) == 1) {
          if (m(c) < lo(c)) {
            bin = fb(c)
            done = 1
          }
        }
        if (hashi(c) == 1) {
          if (m(c) > hi(c)) {
            bin = fb(c)
            done = 1
          }
        }
      }
    }
  }

  # Marginal check: |v - L| <= |L|/10  <=>  10*|v - L| <= |L|
  if (done == 0) {
    mar = 0
    for (c = 1; c <= 5; c = c + 1) {
      if (nmf(c) == 0) {
        if (haslo(c) == 1) {
          if (10 * abs(m(c) - lo(c)) <= abs(lo(c))) mar = 1
        }
        if (hashi(c) == 1) {
          if (10 * abs(m(c) - hi(c)) <= abs(hi(c))) mar = 1
        }
      }
    }
    if (mar == 1) bin = 10
    else bin = 1
  }

  write(6,*) ix, iy, bin
}
end

