integer n, i, j, k, x, y, done, marg, bin, d
integer ord(5), lo(5), hi(5), fb(5), nb(5), m(5)
double precision raw(5)

read(5,*) n

# priority order: FMAX(3), VDD(2), RDS(1), ILEAK(4), VTH(5)
ord(1) = 3; ord(2) = 2; ord(3) = 1; ord(4) = 4; ord(5) = 5

# limits and fail bins, in thousandths (values have at most 3 decimals)
# 2000000000 means no high limit
lo(1) = 144783;  hi(1) = 2000000000; fb(1) = 27; nb(1) = 34
lo(2) = 44244;   hi(2) = 57356;      fb(2) = 21; nb(2) = 34
lo(3) = 211279;  hi(3) = 266253;     fb(3) = 32; nb(3) = 0
lo(4) = 312485;  hi(4) = 527767;     fb(4) = 24; nb(4) = 34
