        d = abs(m(j) - lo(j))
        if (10 * d <= abs(lo(j))) marg = 1
        if (hi(j) != 2000000000) {
          d = abs(m(j) - hi(j))
          if (10 * d <= abs(hi(j))) marg = 1
        }
      }
