integer n, i, k, c, bin, x, y, fb(3)
double precision v(3), lo(3), hi(3)

# column 1 = IDDQ, column 2 = FMAX, column 3 = VDD
lo(1) = 376.044d0; hi(1) = 517.376d0; fb(1) = 33
lo(2) = 107.095d0; hi(2) = 159.905d0; fb(2) = 30
lo(3) = 12.444d0;  hi(3) = 19.156d0;  fb(3) = 32

read(5,*) n
do i = 1, n {
  read(5,*) x, y, v(1), v(2), v(3)
  bin = 0
  # priority 1 = column 3, priority 2 = column 2, priority 3 = column 1
  do k = 1, 3 {
    c = 4 - k
    if (v(c) == -9999d0) { bin = 26; break }
    if (v(c) < lo(c) | v(c) > hi(c)) { bin = fb(c); break }
  }
  if (bin == 0) {
    # marginal: within 2% of any limit (inclusive), checked with integer-free scaling
    do c = 1, 3 {
      if (100d0*abs(v(c)-lo(c)) <= 2d0*abs(lo(c)) | 100d0*abs(v(c)-hi(c)) <= 2d0*abs(hi(c)))
        bin = 15
    }
  }
  if (bin == 0) bin = 1
  write(6,*) x, y, bin
}
end

