hi(1) = 517.376d0
fb(1) = 33
lo(2) = 107.095d0
hi(2) = 159.905d0
fb(2) = 30
lo(3) = 12.444d0
hi(3) = 19.156d0
fb(3) = 32

# priority order: VDD (3), FMAX (2), IDDQ (1)
ord(1) = 3
ord(2) = 2
ord(3) = 1

do i = 1, n {
  read(5,*) x, y, (v(k), k = 1, 3)

  bin = 0
  for (p = 1; p <= 3 & bin == 0; p = p + 1) {
    t = ord(p)
    if (v(t) == -9999d0) {
      bin = 26
    }
    else if (v(t) < lo(t) | v(t) > hi(t)) {
      bin = fb(t)
    }
  }

  if (bin == 0) {
    marg = 0
    for (t = 1; t <= 3; t = t + 1) {
      if (v(t) != -9999d0) {
        d = abs(v(t) - lo(t))
        if (d <= 0.02d0 * abs(lo(t)) + 1d-9) marg = 1
        d = abs(v(t) - hi(t))
