  read(5,*) x, y, (r(c), c = 1, 3)
  for (c = 1; c <= 3; c = c + 1) {
    if (r(c) == -9999d0) {
      miss(c) = 1
      v(c) = 0
    } else {
      miss(c) = 0
      v(c) = nint(r(c) * 1000d0)
    }
  }

  done = 0
  bin = 0
