        if (hasHi(c) == 1 & abs(v(c) - hi(c)) * 100 <= 5 * abs(hi(c))) marg = 1
      }
    }
    if (marg == 1) bin = 18
    else bin = 1
  }

  write(6,*) x, y, bin
}
end

