  if (done == 0) {
    marg = 0
    if ((abs(gs-gl)*10d0 <= abs(gl)) | (abs(gs-gh)*10d0 <= abs(gh))) marg = 1
    if (r != -9999d0) {
      if ((abs(rs-rl)*10d0 <= abs(rl)) | (abs(rs-rh)*10d0 <= abs(rh))) marg = 1
    }
    if (marg == 1) bin = 11
    else bin = 1
  }
